pub fn retain<T, F>(&mut self, mut f: F)
where
    F: FnMut(&T) -> bool,
{
    let mut deleted = 0;
    let original_len = self.len();

    for i in 0..original_len {
        if !f(&self[i]) {
            deleted += 1;
        } else if deleted > 0 {
            self.swap(i - deleted, i);
        }
    }
    self.truncate(original_len - deleted);
}
